use vstd::prelude::*;
use vstd::vec::*;

verus! {

pub fn zeros_like(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i && i < result.len() ==> result[i] == 0,
        forall|other: Vec<i32>|
            other.len() == result.len() ==> (
                forall|i: int| 0 <= i && i < result.len() ==> 
                    (result[i] + other[i]) == other[i] && (other[i] + result[i]) == other[i]
            ),
{
    let mut result_vec = Vec::new();
    let mut n: usize = 0;
    
    while n < a.len()
        invariant
            result_vec.len() == n,
            forall|i: int| 0 <= i && i < n ==> result_vec[i] == 0,
            n <= a.len(),
    {
        result_vec.push(0);
        n = n + 1;
    }
    
    result_vec
}

#[verifier(external)]
fn main() {
    let v1 = vec![1, 2, 3, 4, 5];
    let z1 = zeros_like(&v1);
    println!("Input: {:?}", v1);
    println!("Zeros: {:?}", z1);
    assert!(z1.len() == v1.len());
    
    let v2: Vec<i32> = vec![];
    let z2 = zeros_like(&v2);
    println!("Empty input: {:?}", v2);
    println!("Empty zeros: {:?}", z2);
    assert!(z2.len() == 0);
}

} // verus!